package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import java.util.concurrent.*;import org.json.*;
public class IptvActivity extends Activity{
 static volatile IptvActivity active,channelSource;
 static void changeEpisode(int delta,String id){IptvActivity source=channelSource;if(source==null||source.isFinishing()||source.web==null)return;source.runOnUiThread(()->{if(source.web!=null)source.web.evaluateJavascript("if(window.IptvUI)IptvUI.changeEpisode("+delta+","+JSONObject.quote(id)+").then(function(r){if(!r.sent&&r.message)IptvNative.playerNotice(r.message);})",null);});}
 static void changeLive(int delta,String id){IptvActivity source=channelSource;if(source==null||source.isFinishing()||source.web==null)return;source.runOnUiThread(()->{if(source.web!=null)source.web.evaluateJavascript("if(window.IptvUI)IptvUI.changeLive("+delta+","+JSONObject.quote(id)+")",null);});}private WebView web;private boolean imeVisible;private final ExecutorService worker=Executors.newFixedThreadPool(3),playback=Executors.newSingleThreadExecutor();
 protected boolean standalone(){return false;}
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!standalone()&&!TvActivity.serverRunning){startActivity(new Intent(this,TvActivity.class).putExtra("openPlay",true));finish();return;}getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);web=new WebView(this){@Override public android.view.inputmethod.InputConnection onCreateInputConnection(android.view.inputmethod.EditorInfo info){android.view.inputmethod.InputConnection connection=super.onCreateInputConnection(info);info.imeOptions|=android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI|android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN;return connection;}};setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setUseWideViewPort(true);settings.setSupportZoom(false);settings.setBuiltInZoomControls(false);settings.setDisplayZoomControls(false);settings.setTextZoom(100);settings.setLoadWithOverviewMode(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowUniversalAccessFromFileURLs(true);web.addJavascriptInterface(new Bridge(),"IptvNative");web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){if(getIntent().getBooleanExtra("showSettings",false)){getIntent().removeExtra("showSettings");v.evaluateJavascript("if(window.IptvUI)IptvUI.settings()",null);}}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});web.getViewTreeObserver().addOnGlobalLayoutListener(()->{android.graphics.Rect visible=new android.graphics.Rect();web.getWindowVisibleDisplayFrame(visible);boolean shown=web.getRootView().getHeight()-visible.bottom>web.getRootView().getHeight()/5;if(imeVisible&&!shown)web.evaluateJavascript("if(window.IptvUI)IptvUI.keyboardClosed()",null);imeVisible=shown;});web.loadUrl("file:///android_asset/iptv/index.html");}
 static void play(Context context,JSONObject item)throws Exception{if(context instanceof IptvActivity)channelSource=(IptvActivity)context;String url=IptvStore.get(context).playback(item);JSONObject profile=IptvStore.get(context).summary();try{PlaybackHistory.remember(context,profile.optString("profileId","default"),item);}catch(Exception ignored){}String resumeKey=PlaybackMemory.key(PlaybackMemory.account(context,profile.optString("profileId","default")),item.optString("kind"),item.optString("id"));if(item.optBoolean("startOver",false))PlaybackMemory.put(context,resumeKey,0,0);Intent intent=new Intent(context,PlayerActivity.class).putExtra("phone",context instanceof PhoneIptvActivity).putExtra("itemKind",item.optString("kind")).putExtra("itemId",item.optString("id")).putExtra("poster",item.optString("icon")).putExtra("resumeKey",resumeKey).putExtra("live",item.optString("kind").equals("live")).putExtra("url",url).putExtra("name",item.optString("name","Morph IPTV"));PlayerActivity player=PlayerActivity.active;if((item.optString("kind").equals("live")||item.optString("kind").equals("episode"))&&player!=null&&player.replacePlayback(intent))return;context.startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 JSONObject remote(String method,String value)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] output={null};runOnUiThread(()->web.evaluateJavascript("JSON.stringify(IptvUI.remote("+JSONObject.quote(method)+","+JSONObject.quote(value)+"))",r->{output[0]=r;done.countDown();}));if(!done.await(5,TimeUnit.SECONDS))throw new Exception("المكتبة لم تستجب.");return new JSONObject(String.valueOf(new JSONTokener(output[0]).nextValue()));}
 public final class Bridge{
  @JavascriptInterface public void playerNotice(String message){if(message==null)return;String text=message.substring(0,Math.min(200,message.length()));runOnUiThread(()->android.widget.Toast.makeText(IptvActivity.this,text,android.widget.Toast.LENGTH_LONG).show());}
  @JavascriptInterface public void request(String id,String action,String data){(action.equals("play")?playback:worker).execute(()->{boolean ok=true;Object response;try{JSONObject payload=new JSONObject(data);IptvStore store=IptvStore.get(IptvActivity.this);if(action.equals("history"))response=store.history();else if(action.equals("epg"))response=store.epg(payload.optString("id"));else if(action.equals("connect"))response=store.connect(payload);else if(action.equals("summary"))response=store.summary();else if(action.equals("categories"))response=store.categories(payload.optString("kind","live"));else if(action.equals("list"))response=store.list(payload);else if(action.equals("refresh")){store.refresh();response=new JSONObject().put("refreshed",true);}else if(action.equals("settings"))response=UiSettings.get(IptvActivity.this);else if(action.equals("saveSettings"))response=UiSettings.save(IptvActivity.this,payload);else if(action.equals("clearProgress")){PlaybackMemory.clear(IptvActivity.this);response=new JSONObject().put("cleared",true);}else if(action.equals("progress"))response=store.progress(payload.optJSONArray("items"));else if(action.equals("details"))response=store.details(payload);else if(action.equals("play")){play(IptvActivity.this,payload);response=new JSONObject().put("sent",true);}else throw new Exception("Unsupported action");}catch(Exception e){ok=false;response=e.getMessage()==null?"تعذّر تحميل المكتبة.":e.getMessage();}final boolean success=ok;final Object value=response;runOnUiThread(()->web.evaluateJavascript("window.iptvResult("+JSONObject.quote(id)+","+success+","+(value instanceof JSONObject?value.toString():JSONObject.quote(String.valueOf(value)))+");",null));});}
  @JavascriptInterface public void showKeyboard(String id,String value){if(!java.util.Arrays.asList("unified-query","account-server","account-user","account-password","account-name").contains(id))return;runOnUiThread(()->{if(isFinishing()||web==null)return;web.requestFocus();web.evaluateJavascript("document.getElementById("+JSONObject.quote(id)+").readOnly=false;document.getElementById("+JSONObject.quote(id)+").focus()",r->{android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime!=null)ime.showSoftInput(web,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});});}
  @JavascriptInterface public void hideKeyboard(){runOnUiThread(()->{android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime!=null&&web!=null)ime.hideSoftInputFromWindow(web.getWindowToken(),0);});}
  @JavascriptInterface public String performanceMode(){return UiSettings.prefs(IptvActivity.this).getString("performanceMode","light");}@JavascriptInterface public String deviceInfo(){try{return DeviceCapabilities.info(IptvActivity.this).toString();}catch(Exception e){return "{}";}}@JavascriptInterface public String settingsJson(){try{return UiSettings.get(IptvActivity.this).toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void radio(){runOnUiThread(()->AppLocks.guard(IptvActivity.this,"local.tvmorph.tv.radio",()->startActivity(new Intent(IptvActivity.this,RadioActivity.class))));}
  @JavascriptInterface public void exit(){runOnUiThread(()->finish());}
 }
 @Override protected void onResume(){super.onResume();ParentalTimer.enter(this,"local.tvmorph.tv.play");if(!isFinishing())active=this;if(web!=null)web.evaluateJavascript("if(window.IptvUI)IptvUI.resume()",null);}
 @Override protected void onPause(){ParentalTimer.leave("local.tvmorph.tv.play");if(active==this)active=null;super.onPause();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("showSettings",false)&&web!=null){intent.removeExtra("showSettings");web.evaluateJavascript("if(window.IptvUI)IptvUI.settings()",null);}else if(web!=null)web.reload();}
 @Override public void onBackPressed(){web.evaluateJavascript("IptvUI.back()",null);}
 @Override protected void onDestroy(){if(channelSource==this)channelSource=null;worker.shutdownNow();playback.shutdownNow();if(web!=null)web.destroy();super.onDestroy();}
 @Override public boolean dispatchKeyEvent(android.view.KeyEvent event){
  if(event.getKeyCode()==android.view.KeyEvent.KEYCODE_DPAD_CENTER&&web!=null){
   if(event.getAction()==android.view.KeyEvent.ACTION_DOWN||event.getAction()==android.view.KeyEvent.ACTION_UP){String type=event.getAction()==android.view.KeyEvent.ACTION_DOWN?"keydown":"keyup";web.evaluateJavascript("(function(){var e=new Event('"+type+"',{bubbles:true,cancelable:true});Object.defineProperty(e,'keyCode',{value:13});Object.defineProperty(e,'repeat',{value:"+(event.getRepeatCount()>0)+"});(document.activeElement||document).dispatchEvent(e);})()",null);}return true;
  }return super.dispatchKeyEvent(event);
 }

}
